  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <meta http-equiv="Content-Security-Policy" content="default-src 'self'; style-src 'self' 'unsafe-inline'; script-src 'self'">
  <title>Theme Picker</title>
  <style>
    :root {
      --bg-color: #ffffff;
      --text-color: #1a1a1a;
      --accent-color: #4a90d9;
    }

    [data-theme="dark"] {
      --bg-color: #1a1a1a;
      --text-color: #e0e0e0;
      --accent-color: #6ab0f3;
    }

    body {
      background-color: var(--bg-color);
      color: var(--text-color);
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
      display: flex;
      justify-content: center;
      align-items: center;
      min-height: 100vh;
      margin: 0;
      transition: background-color 0.3s ease, color 0.3s ease;
    }

    .container {
      text-align: center;
      padding: 2rem;
    }

    h1 {
      margin-bottom: 2rem;
    }

    .theme-buttons {
      display: flex;
      gap: 1rem;
      justify-content: center;
    }

    button {
      padding: 0.75rem 1.5rem;
      font-size: 1rem;
      border: 2px solid var(--accent-color);
      border-radius: 8px;
      background: transparent;
      color: var(--text-color);
      cursor: pointer;
      transition: all 0.2s ease;
    }

    button:hover {
      background-color: var(--accent-color);
      color: #ffffff;
    }

    button.active {
      background-color: var(--accent-color);
      color: #ffffff;
    }
  </style>
</head>
<body>
  <div class="container">
    <h1>Choose Your Theme</h1>
    <div class="theme-buttons">
      <button id="light-btn" data-theme-value="light">Light</button>
      <button id="dark-btn" data-theme-value="dark">Dark</button>
    </div>
  </div>

  <script src="theme-picker.js"></script>
  <script>
    // Initialize theme picker and set up button handlers
    (async () => {
      const currentTheme = await window.ThemePicker.initialize();
      updateActiveButton(currentTheme);

      document.getElementById('light-btn').addEventListener('click', async () => {
        const theme = await window.ThemePicker.setTheme('light');
        window.ThemePicker.applyTheme(theme);
        updateActiveButton(theme);
      });

      document.getElementById('dark-btn').addEventListener('click', async () => {
        const theme = await window.ThemePicker.setTheme('dark');
        window.ThemePicker.applyTheme(theme);
        updateActiveButton(theme);
      });

      function updateActiveButton(theme) {
        document.querySelectorAll('button[data-theme-value]').forEach(btn => {
          btn.classList.toggle('active', btn.dataset.themeValue === theme);
        });
      }
    })();
  </script>
